// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }
    function testRegression_property() public {
        Token token = new Token();
        vm.prank(address(this));
        token.approve(address(c), 100);
        address[] memory tos = new address[](1);
        tos[0] = address(0x123);
        bool ok;
        try c.transfer(address(this), address(token), tos, 100) {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 balance = token.balanceOf(address(0x123));
        assertTrue(ok && balance == 100);
    }
}

contract Token {
    mapping(address => mapping(address => uint256)) public allowance;
    mapping(address => uint256) public balanceOf;
    function approve(address spender, uint256 amount) public returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }
    function transferFrom(address from, address to, uint256 amount) public returns (bool) {
        require(allowance[from][msg.sender] >= amount);
        allowance[from][msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}
